#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
printf '%s\n' '=== Basic Case Statement Example ==='
case "$1" in
    "start")
        echo 'Starting the service...'
    ;;
    "stop")
        echo 'Stopping the service...'
    ;;
    "restart")
        echo 'Restarting the service...'
    ;;
    *)
        printf '%s\n' "Usage: $0 {start|stop|restart}"
        exit 1
    ;;
esac
printf '%s\n' '=== Case Statement with Pattern Matching ==='
filename="$2"
case "$filename" in
    *.txt)
        printf '%s\n' "Processing text file: $filename"
    ;;
    *.sh)
        printf '%s\n' "Processing shell script: $filename"
    ;;
    *.py)
        printf '%s\n' "Processing Python file: $filename"
    ;;
    *)
        printf '%s\n' "Unknown file type: $filename"
    ;;
esac
printf '%s\n' '=== Case Statement with Multiple Patterns ==='
case "$3" in
    "help" | "h" | "-h" | "--help")
        echo 'Help information:'
        echo '  start  - Start the service'
        echo '  stop   - Stop the service'
        echo '  status - Show service status'
    ;;
    "status" | "s" | "-s" | "--status")
        echo 'Service status: Running'
    ;;
    *)
        printf '%s\n' "Unknown option: $3"
    ;;
esac
printf '%s\n' '=== Case Statement with Character Classes ==='
case "$4" in
    [0-9])
        printf '%s\n' "Single digit: $4"
    ;;
    [a-z])
        printf '%s\n' "Lowercase letter: $4"
    ;;
    [A-Z])
        printf '%s\n' "Uppercase letter: $4"
    ;;
    [0-9][0-9])
        printf '%s\n' "Two digit number: $4"
    ;;
    *)
        printf '%s\n' "Other character: $4"
    ;;
esac
printf '%s\n' '=== Case Statement with Default Action ==='
case "$5" in
    "red")
        echo 'Color is red'
    ;;
    "green")
        echo 'Color is green'
    ;;
    "blue")
        echo 'Color is blue'
    ;;
esac
printf '%s\n' '=== Case Statement with Commands ==='
case "$6" in
    "ls")
        ls -l -a
    ;;
    "date")
        date
    ;;
    "pwd")
        pwd
    ;;
    "whoami")
        whoami
    ;;
    *)
        echo 'Available commands: ls, date, pwd, whoami'
    ;;
esac
